    const more=compact?'':`${this._config.show_graph===false?'':`<section><div class="section-title">Puissance instantanée <small>Historique depuis l’ouverture de la carte, max. 1 h</small></div>${this.graph()}<div class="legend"><span>● Puissance soutirée (W)</span><span>● Puissance injectée</span></div></section>`}<section><div class="section-title">Index tarifaires</div><div class="indexes">${[1,2,3,4,5,6].filter(i=>this.state('index_'+i)).map(i=>`<div><span>${esc(indexLabel(this.state('index_'+i)?.attributes?.friendly_name||'Index '+i,this.value('contract_name')))}</span><strong>${this.fmt('index_'+i,'kWh',1000,2)}</strong></div>`).join('')}</div></section><section><div class="section-title">Mesures et diagnostic</div><div class="indexes"><div><span>Intensité</span><strong>${this.fmt('current','A')}</strong></div><div><span>Tension</span><strong>${this.fmt('voltage','V')}</strong></div><div><span>État TIC</span><strong>${esc(this.value('tic_state')||'—')}</strong></div><div><span>Contrat</span><strong>${esc(this.value('contract_name')||'—')}</strong></div><div><span>Période fournisseur actuelle</span><strong>${esc(this.value('supplier_today')??'—')}</strong></div><div><span>Période fournisseur demain</span><strong>${esc(this.value('supplier_tomorrow')??'—')}</strong></div></div></section>${this.relaySection()}`;
    const markup=`<style>:host{display:block;color:var(--primary-text-color);font-family:var(--paper-font-body1_-_font-family,inherit)}ha-card{padding:18px;border-radius:var(--ha-card-border-radius,14px);overflow:hidden}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.title{font-size:18px;font-weight:650}.pill{font-size:12px;padding:5px 10px;border-radius:20px;background:var(--secondary-background-color);text-align:right}.tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.tile{background:var(--secondary-background-color);padding:14px;border-radius:12px;min-width:0}.label,.sub{font-size:12px;color:var(--secondary-text-color)}.value{font-size:24px;font-weight:700;margin:5px 0;white-space:nowrap}.gauge-layout{display:flex;align-items:center;gap:10px;min-width:0}.gauge{width:clamp(96px,50%,150px);flex:none}.gauge svg{width:100%;height:auto;aspect-ratio:1;background:none;border-radius:0;overflow:visible}.gauge-number{font-size:24px;font-weight:700;fill:var(--primary-text-color)}.gauge-unit{font-size:12px;font-weight:600;fill:var(--secondary-text-color)}.gauge-info{min-width:0;flex:1}.gauge-label{font-size:13px;font-weight:650}.gauge-reading{font-size:12px;font-weight:600;margin-top:5px}.gauge-range{font-size:10px;color:var(--secondary-text-color);margin-top:5px}.gauge-tile .sub{margin-top:6px}@media(max-width:540px){.gauge-layout{flex-direction:column;gap:2px}.gauge{width:min(100%,125px)}.gauge-info{text-align:center}.gauge-label{font-size:12px}.gauge-reading{font-size:11px}}.import{--gauge-color:#dc932c}.export{--gauge-color:#e6ad23}.import .value{color:#dc932c}.export .value{color:#e6ad23}section{margin-top:20px}.section-title{font-weight:650;margin-bottom:10px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:5px}.section-title small{font-weight:400;color:var(--secondary-text-color);font-size:11px}svg{width:100%;height:130px;display:block;background:var(--secondary-background-color);border-radius:9px}.legend{display:flex;gap:20px;font-size:12px;margin-top:6px;color:var(--secondary-text-color)}.legend span:first-child{color:#dc932c}.legend span:last-child{color:#269e8c}.indexes>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--divider-color);padding:8px 0;font-size:13px}.indexes span{min-width:0;overflow-wrap:anywhere;color:var(--secondary-text-color)}.indexes strong{text-align:right;white-space:nowrap}.empty{padding:25px 12px;text-align:center;font-size:12px;color:var(--secondary-text-color);background:var(--secondary-background-color);border-radius:9px}.foot{margin-top:12px;font-size:11px;color:var(--secondary-text-color)}@media(max-width:370px){.value{font-size:19px}.tile{padding:10px}}</style><ha-card><div class="top"><div class="title">${esc(this._config.title)}</div><div class="pill"><ha-icon icon="${tariffIcon(period)}" style="--mdc-icon-size:18px;vertical-align:middle;margin-right:5px"></ha-icon>${esc(period)}</div></div><div class="tiles">${powerTiles}${tile('Énergie soutirée aujourd’hui',this.fmt('consumption_today','kWh',1000,2),'Depuis minuit')}${tile('Énergie injectée aujourd’hui',this.fmt('production_today','kWh',1000,2),'Depuis minuit')}</div>${more}<div class="foot">Mesures MQTT · Soutirage en W calculé à partir des VA (coefficient indicatif : 0,95)</div></ha-card>`;
